/**
 * POST /api/build/artifact — generate ONE builder-pivot artifact from the user's
 * idea (#207). This is the wiring that makes the /build flow real: each artifact
 * (thesis, wedge, PRD, data model, …) is generated by Claude from the founder's
 * idea, instead of rendering the hardcoded design mock.
 *
 * Provider order (reuses the SAME completion stack as codegen, no new provider):
 *   1. Amazon Bedrock (Config C) or direct Anthropic  — lib/build/claude-completion
 *   2. AINative chat-completions (claude-sonnet-4.5)   — OpenAI-compatible, server key
 * Both work server-side for ANY visitor (incl. anonymous), so nobody is blocked.
 * The enterprise-gated agent-swarm path is reserved for the paid real-build step
 * (see core#6422).
 *
 * Body: { view, idea, track, companyName?, prior? }
 * Returns: { view, content (parsed JSON per artifact schema), provider, model }
 */

import { NextRequest } from 'next/server'
import OpenAI from 'openai'
import { ARTIFACT_PROMPTS, type ArtifactContext } from '@/lib/build/artifact-prompts'
import { getClaudeCompletion } from '@/lib/build/claude-completion'

export const runtime = 'nodejs'

const ainative = new OpenAI({
  apiKey: process.env.AINATIVE_API_KEY || process.env.API_Key || process.env.ZERODB_API_KEY || '',
  baseURL: (process.env.AINATIVE_API_URL || 'https://api.ainative.studio') + '/v1',
})
const AINATIVE_CLAUDE = process.env.BUILD_ARTIFACT_MODEL || 'claude-sonnet-4.5'
const AINATIVE_FALLBACK = 'nous-coder'

/** Pull the first balanced JSON object out of a model response (handles ```json fences, stray prose). */
function parseJson(raw: string): unknown | null {
  if (!raw) return null
  let s = raw.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()
  const start = s.indexOf('{')
  const end = s.lastIndexOf('}')
  if (start === -1 || end === -1 || end < start) return null
  s = s.slice(start, end + 1)
  try {
    return JSON.parse(s)
  } catch {
    return null
  }
}

export async function POST(request: NextRequest) {
  let body: any
  try {
    body = await request.json()
  } catch {
    return Response.json({ error: 'invalid JSON body' }, { status: 400 })
  }

  const { view, idea, track, companyName, prior } = body || {}
  if (!view || !ARTIFACT_PROMPTS[view]) {
    return Response.json({ error: `unknown or missing view: ${view}` }, { status: 400 })
  }
  if (!idea || typeof idea !== 'string' || idea.trim().length < 3) {
    return Response.json({ error: 'idea is required' }, { status: 400 })
  }

  const spec = ARTIFACT_PROMPTS[view]
  const ctx: ArtifactContext = {
    idea: idea.trim().slice(0, 4000),
    track: track === 'company' ? 'company' : 'app',
    companyName: typeof companyName === 'string' ? companyName.slice(0, 120) : undefined,
    prior: prior && typeof prior === 'object' ? prior : {},
  }
  const system = spec.system + `\nRequired JSON schema: ${spec.schemaHint}`
  const user = spec.user(ctx)

  // 1) Primary: Bedrock / direct Anthropic (provider-agnostic .messages.create)
  const claude = getClaudeCompletion()
  if (claude) {
    try {
      const res = await claude.client.messages.create({
        model: claude.model,
        max_tokens: 1600,
        temperature: 0.55,
        system,
        messages: [{ role: 'user', content: user }],
      })
      const text = (res.content || [])
        .filter((b: any) => b.type === 'text')
        .map((b: any) => b.text)
        .join('\n')
      const content = parseJson(text)
      if (content) {
        return Response.json({ view, content, provider: claude.provider, model: claude.model })
      }
      console.warn(`[build/artifact] ${view}: ${claude.provider} returned unparseable JSON, falling back`)
    } catch (e: any) {
      console.warn(`[build/artifact] ${view}: ${claude.provider} failed (${e?.message?.slice(0, 80)}), falling back`)
    }
  }

  // 2) Fallback: AINative chat-completions (claude-sonnet-4.5, then a free model)
  for (const model of [AINATIVE_CLAUDE, AINATIVE_FALLBACK]) {
    try {
      const res = await ainative.chat.completions.create({
        model,
        max_tokens: 1600,
        temperature: 0.55,
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: user },
        ],
      })
      const text = res.choices?.[0]?.message?.content || ''
      const content = parseJson(text)
      if (content) {
        return Response.json({ view, content, provider: 'ainative', model })
      }
    } catch (e: any) {
      console.warn(`[build/artifact] ${view}: ainative ${model} failed (${e?.message?.slice(0, 80)})`)
    }
  }

  return Response.json(
    { error: 'generation_unavailable', view },
    { status: 503 },
  )
}
